def f(N: int, segments: List[Tuple[int, int, int, int]]) -> int:
    segments.sort(key=lambda x: x[0])
    total = 0
    for i in range(1, N):
        if segments[i][0] > segments[i - 1][1]:
            total += segments[i][0] - segments[i - 1][1]
        else:
            total += segments[i][1] - segments[i - 1][0]
    return total
```

